EURO = """1967 Celtic|1972 Rangers|1983 Aberdeen|1984 Aberdeen"""  # Aberdeen CWC May 1983 (1982-83), Super Cup Dec 1983 (1983-84 season)
def parse(s, t):
    out=[]
    for item in s.split('|'):
        y, cs = item.split(' ',1)
        for c in cs.split(';'): out.append((int(y), c, t))
    return out
WINS = parse(LEAGUE,'L')+parse(CUP,'F')+parse(LCUP,'C')+parse(EURO,'E')
